func NewDispatcher(
	alerts provider.Alerts,
	route *Route,
	stage notify.Stage,
	marker types.GroupMarker,
	timeout func(time.Duration) time.Duration,
	maintenanceInterval time.Duration,
	limits Limits,
	logger *slog.Logger,
	metrics *DispatcherMetrics,
) *Dispatcher {
	if limits == nil {
		limits = nilLimits{}
	}

	disp := &Dispatcher{
		alerts:              alerts,
		stage:               stage,
		route:               route,
		marker:              marker,
		timeout:             timeout,
		maintenanceInterval: maintenanceInterval,
		logger:              logger.With("component", "dispatcher"),
		metrics:             metrics,
		limits:              limits,
		state:               DispatcherStateUnknown,
	}
	return disp
}
", "id": "SRC-CU-HELPER-62b5e84fb39809d4", "kind": "SOURCE_SPAN", "locator": {"end_line": 142, "path": "dispatch/dispatch.go", "start_line": 113}, "origin": "selected candidate CU-HELPER-62b5e84fb39809d4", "snapshot_id": "007325c7f55977c4afd2dfae9e3213373126ad9d11f0854be1d3f54f8fe89308"}, {"content_digest": "13a71921161828220a17087f71c92d0acb56c2c2f3b9e8b2cb5869d48c63c63b", "excerpt": "func (ih *Inhibitor) run(ctx context.Context) {
	it := ih.alerts.Subscribe("inhibitor")
	defer it.Close()

	for {
		select {
		case <-ctx.Done():
			return
		case a := <-it.Next():
			if err := it.Err(); err != nil {
				ih.logger.Error("Error iterating alerts", "err", err)
				continue
			}
			// Update the inhibition rules' cache.
			cachedSum := 0
			indexedSum := 0
			for _, r := range ih.rules {
				if r.SourceMatchers.Matches(a.Labels) {
					if err := r.scache.Set(a); err != nil {
						ih.logger.Error("error on set alert", "err", err)
						continue
					}
					r.updateIndex(a)

				}
				cached := r.scache.Len()
				indexed := r.sindex.Len()

				if r.Name != "" {
					r.metrics.sourceAlertsCacheItems.With(prometheus.Labels{"rule": r.Name}).Set(float64(cached))
					r.metrics.sourceAlertsIndexItems.With(prometheus.Labels{"rule": r.Name}).Set(float64(indexed))
				}

				cachedSum += cached
				indexedSum += indexed
			}
			ih.metrics.sourceAlertsCacheItems.Set(float64(cachedSum))
			ih.metrics.sourceAlertsIndexItems.Set(float64(indexedSum))
		}
	}
}
